//! Round 42: eigenvectors of matrices with parameters, as null spaces over the field generated by the eigenvalue
//! over the rational functions of the parameters.
use mc_api::{Engine, StopFlag};
use mc_engine::CoreEngine;

fn ev(e: &mut CoreEngine, src: &str) -> String {
    e.eval(src, &StopFlag::new()).map(|r| r.printed).unwrap_or_else(|err| format!("error: {err:?}"))
}

fn same(e: &mut CoreEngine, src: &str, expected: &str) {
    let got = ev(e, src);
    let want = ev(e, expected);
    assert_eq!(got, want, "{src}");
}

#[test]
fn two_by_two_with_four_parameters() {
    let mut e = CoreEngine::new();
    let s = "(-2*a*g + 4*b*c + a^2 + g^2)^(1/2)";
    same(&mut e, "eigenvectors([[a, b], [c, g]])", &format!("[[(a - g - {s})/(2*c), 1], [(a - g + {s})/(2*c), 1]]"));
    same(
        &mut e,
        "eigensystem([[a, b], [c, g]])",
        &format!("[[(a + g - {s})/2, (a + g + {s})/2], [[(a - g - {s})/(2*c), 1], [(a - g + {s})/(2*c), 1]]]"),
    );
    // independent check: m v = lambda v after simplification, for both pairs
    ev(&mut e, "es = eigensystem([[a, b], [c, g]])");
    assert_eq!(ev(&mut e, "map(k => simplify(dot([[a, b], [c, g]], es[2][k]) - es[1][k]*es[2][k]), [1, 2])"), "[[0, 0], [0, 0]]");
    // variations: another quadratic in a parameter, and a matrix whose eigenvalues are rational functions
    ev(&mut e, "es = eigensystem([[p, 1], [q, p]])");
    assert_eq!(ev(&mut e, "map(k => simplify(dot([[p, 1], [q, p]], es[2][k]) - es[1][k]*es[2][k]), [1, 2])"), "[[0, 0], [0, 0]]");
    same(&mut e, "eigenvectors([[a, b], [b, a]])", "[[-1, 1], [1, 1]]");
}

#[test]
fn cubic_factors_give_polynomials_in_the_root() {
    let mut e = CoreEngine::new();
    // the roots of the monic characteristic polynomial (its factor with a positive leading coefficient)
    ev(&mut e, "vals = eigenvalues([[a, 2, 0], [2, 3, 1], [0, 1, 7]])");
    assert_eq!(ev(&mut e, "map(k => vals[k][2], [1, 2, 3])"), "[1, 2, 3]");
    assert_eq!(ev(&mut e, "expand(vals[1][1](t) - (28 - 20*a + (16 + 10*a)*t + (-10 - a)*t^2 + t^3))"), "0");
    // the first eigenvector: last entry 1, the others polynomials in the root of degree below 3
    same(
        &mut e,
        "rewrite(eigenvectors([[a, 2, 0], [2, 3, 1], [0, 1, 7]])[1], root(_, 1) -> t)",
        "[(1/2)*(20 - 10*t + t^2), -7 + t, 1]",
    );
    // independent check: with the root replaced by t, (m - t) v reduces to 0 modulo det(t - m)
    ev(&mut e, "m = [[a, 2, 0], [2, 3, 1], [0, 1, 7]]");
    ev(&mut e, "w = rewrite(eigenvectors(m)[2], root(_, 2) -> t)");
    assert_eq!(
        ev(&mut e, "map(c => polynomial_remainder(expand(c), characteristic_polynomial(m, t), t), dot(m, w) - t*w)"),
        "[0, 0, 0]"
    );
    // variations: the companion matrix of a general cubic, and a numeric value of the parameter against the
    // machine eigenvectors (parallel vectors)
    ev(&mut e, "m2 = [[0, 1, 0], [0, 0, 1], [a, b, c]]");
    ev(&mut e, "w2 = rewrite(eigenvectors(m2)[3], root(_, 3) -> t)");
    assert_eq!(
        ev(&mut e, "map(c => polynomial_remainder(expand(numerator(together(c))), characteristic_polynomial(m2, t), t), dot(m2, w2) - t*w2)"),
        "[0, 0, 0]"
    );
    ev(&mut e, "v = n(rewrite(eigenvectors(m), a -> 5))");
    ev(&mut e, "lam = n(rewrite(eigenvalues(m), a -> 5))");
    assert_eq!(
        ev(&mut e, "all_true(table(norm(dot(rewrite(m, a -> 5), v[k]) - lam[k]*v[k]) < 10^-9, k, 3), x => x)"),
        "true"
    );
}
